# Settings that are fine to publish. Wi-Fi credentials, the collector's URL and
# its token live in device_secrets.py, generated by tools/build.py.

DEVICE_NAME = "early-bird"
WIFI_COUNTRY = "FR"

# Timeout for requests to the OpenTelemetry Collector.
HTTP_TIMEOUT_S = 5

# Tried in order; on failure the next one is used.
NTP_SERVERS = ("time.cloudflare.com", "time.google.com")
NTP_TIMEOUT_S = 2
NTP_RETRY_S = 10
NTP_RESYNC_S = 6 * 3600

SAMPLE_INTERVAL_S = 5  # one data point per interval
EXPORT_INTERVAL_S = 30  # one HTTP request per interval
EXPORT_MAX_POINTS = 12  # data points per HTTP request
QUEUE_MAX_POINTS = 720  # kept in RAM while the collector is unreachable (1 h)

# BH1750 light sensor on I2C0.
I2C_ID = 0
I2C_SDA = 4
I2C_SCL = 5
BH1750_ADDR = 0x23
# Sensitivity, 31 to 254. 254 resolves 0.14 lx and saturates near 7400 lx;
# the chip default of 69 resolves 0.5 lx and saturates near 27000 lx.
BH1750_MTREG = 254

# SPH0645LM4H microphone on I2S. WS must be the GPIO right after SCK.
I2S_ID = 0
I2S_SCK = 16
I2S_WS = 17
I2S_SD = 18
# The microphone wants a 2 to 4 MHz bit clock, which is 64 x the sample rate.
# Sound is analysed in blocks of AUDIO_RATE / 10 samples, 4096 at most.
AUDIO_RATE = 32000

WATCHDOG = True  # reboot if the main loop stalls for 8 s
STATUS_LED = False  # True: onboard LED is lit while Wi-Fi or the clock is down
